[metadata] {"type": "create", "filePath": "/workspace/repo/src/integrations/prefect-kubernetes/prefect_kubernetes/diagnostics.py", "content": """"Structured diagnostics for Kubernetes pod failures.

This module inspects Kubernetes pod status dictionaries and translates known
failure conditions (image pull errors, out-of-memory kills, crash loops,
scheduling failures, evictions, ...) into structured, human-readable
diagnoses that can be surfaced to users via flow run logs.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass
from typing import Any


class DiagnosisLevel(str, enum.Enum):
    """Severity level for an infrastructure diagnosis."""

    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True)
class InfrastructureDiagnosis:
    """A structured diagnosis of a Kubernetes pod failure.

    Instances are immutable (frozen) so that they can be safely cached and
    compared for equality when deduplicating diagnosis logs.
    """

    level: DiagnosisLevel
    summary: str
    detail: str
    resolution: str


# Waiting-state container reasons that indicate an image could not be pulled.
_IMAGE_PULL_REASONS = {"ImagePullBackOff", "ErrImagePull"}


def _iter_container_statuses(status: dict[str, Any]):
    """Yield container statuses from both init and regular containers.

    Init containers are yielded first so that init container failures are
    surfaced before regular container failures.
    """
    for key in ("initContainerStatuses", "containerStatuses"):
        for container_status in status.get(key) or []:
            if isinstance(container_status, dict):
                yield container_status


def _diagnose_waiting(container_statuses: list[dict[str, Any]]):
    """Return a diagnosis for a waiting-state container failure, if any."""
    for container_status in container_statuses:
        name = container_status.get("name", "<unknown>")
        waiting = (container_status.get("state") or {}).get("waiting") or {}
        reason = waiting.get("reason")
        if reason is None:
            continue

        if reason in _IMAGE_PULL_REASONS:
            message = waiting.get("message")
            detail = reason if not message else f"{reason}: {message}"
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=(
                    f"Container '{name}' could not pull its image ({reason})."
                ),
                detail=detail,
                resolution=(
                    "Verify the image name and tag are correct and that the "
                    "cluster has credentials to pull the image from the registry."
                ),
            )

        if reason == "CrashLoopBackOff":
            message = waiting.get("message")
            detail = reason if not message else f"{reason}: {message}"
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=f"Container '{name}' is crash-looping ({reason}).",
                detail=detail,
                resolution=(
                    "Inspect the container logs to determine why the process is "
                    "exiting and address the underlying error."
                ),
            )

    return None


def _diagnose_terminated(container_statuses: list[dict[str, Any]]):
    """Return a diagnosis for a terminated-state container failure, if any."""
    for container_status in container_statuses:
        name = container_status.get("name", "<unknown>")
        terminated = (container_status.get("state") or {}).get("terminated") or {}
        reason = terminated.get("reason")
        if reason is None:
            continue

        if reason == "OOMKilled":
            message = terminated.get("message")
            detail = reason if not message else f"{reason}: {message}"
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=(
                    f"Container '{name}' was OOMKilled (ran out of memory)."
                ),
                detail=detail,
                resolution=(
                    "Increase the memory limit for the container or reduce the "
                    "amount of memory the workload uses."
                ),
            )

        if reason == "Evicted":
            message = terminated.get("message")
            detail = reason if not message else f"{reason}: {message}"
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary=f"Container '{name}' was evicted ({reason}).",
                detail=detail,
                resolution=(
                    "Check node resource pressure and pod resource requests; the "
                    "pod may be rescheduled onto another node."
                ),
            )

    return None


def _diagnose_conditions(status: dict[str, Any]):
    """Return a diagnosis for a problematic pod condition, if any."""
    for condition in status.get("conditions") or []:
        if not isinstance(condition, dict):
            continue
        if (
            condition.get("type") == "PodScheduled"
            and condition.get("reason") == "Unschedulable"
        ):
            message = condition.get("message")
            detail = message if message else "Pod is unschedulable."
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary="Pod is unschedulable.",
                detail=detail,
                resolution=(
                    "Check that the cluster has nodes with sufficient resources "
                    "and that node selectors, affinities, and tolerations can be "
                    "satisfied."
                ),
            )
    return None


def _diagnose_pod_reason(status: dict[str, Any]):
    """Return a diagnosis for a pod-level failure reason, if any."""
    if status.get("reason") == "Evicted":
        message = status.get("message")
        detail = message if message else "Pod was evicted."
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary="Pod was evicted from its node.",
            detail=detail,
            resolution=(
                "Check node resource pressure and pod resource requests; the "
                "pod may be rescheduled onto another node."
            ),
        )
    return None


def diagnose_k8s_pod(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Inspect a pod status dictionary and return a structured diagnosis.

    Args:
        status: A Kubernetes pod ``status`` dictionary.

    Returns:
        An ``InfrastructureDiagnosis`` describing a known failure condition, or
        ``None`` if the pod is healthy or in a state that does not require
        intervention.
    """
    if not status:
        return None

    container_statuses = list(_iter_container_statuses(status))

    # Waiting-state failures take priority over terminated-state failures.
    if (diagnosis := _diagnose_waiting(container_statuses)) is not None:
        return diagnosis

    if (diagnosis := _diagnose_terminated(container_statuses)) is not None:
        return diagnosis

    if (diagnosis := _diagnose_conditions(status)) is not None:
        return diagnosis

    if (diagnosis := _diagnose_pod_reason(status)) is not None:
        return diagnosis

